#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD=998244353;
ll pw(ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
int par[200005];ll sz[200005];
int f(int x){return par[x]==x?x:par[x]=f(par[x]);}
int main(){int t;scanf("%d",&t);while(t--){int n;ll S;scanf("%d %lld",&n,&S);
 vector<array<ll,3>>e(n-1);
 for(auto&x:e)scanf("%lld %lld %lld",&x[1],&x[2],&x[0]);
 sort(e.begin(),e.end());
 for(int i=1;i<=n;i++){par[i]=i;sz[i]=1;}
 ll ans=1;
 for(auto&x:e){int a=f(x[1]),b=f(x[2]);ll w=x[0];
  ll ex=sz[a]*sz[b]-1;
  ans=ans*pw((S-w+1)%MOD,ex)%MOD;
  if(sz[a]<sz[b])swap(a,b);par[b]=a;sz[a]+=sz[b];}
 printf("%lld\n",ans);}}

