#include <bits/stdc++.h>
using namespace std;
static char buf[1000005];
int main(){int t;scanf("%d",&t);
 while(t--){scanf("%s",buf);string s(buf);int n=s.size();
  string T="#";for(char c:s){T+=c;T+='#';}
  int N=T.size();vector<int>P(N,0);int C=0,R=0;
  for(int i=0;i<N;i++){
   if(i<R)P[i]=min(R-i,P[2*C-i]);
   while(i-P[i]-1>=0&&i+P[i]+1<N&&T[i-P[i]-1]==T[i+P[i]+1])P[i]++;
   if(i+P[i]>R){C=i;R=i+P[i];}}
  auto pal=[&](int l,int r){return P[l+r+1]>=r-l+1;};
  if(!pal(0,n-1)){printf("YES\n1\n%s\n",s.c_str());continue;}
  bool constant=true;for(char c:s)if(c!=s[0])constant=false;
  if(constant){printf("NO\n");continue;}
  int found=-1;
  for(int L=1;L<n&&found<0;L++)if(!pal(0,L-1)&&!pal(L,n-1))found=L;
  if(found<0){printf("NO\n");continue;}
  printf("YES\n2\n%s %s\n",s.substr(0,found).c_str(),s.substr(found).c_str());}}

