typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);
 vector<ll>a(n+1);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);
 vector<int>p(n+1,0),dep(n+1,0);vector<vector<int>>ch(n+1);
 for(int i=2;i<=n;i++){scanf("%d",&p[i]);ch[p[i]].push_back(i);dep[i]=dep[p[i]]+1;}
 const ll INF=(ll)1e18;
 vector<ll>cnt(n+1,0);
 for(int v=1;v<=n;v++)if(ch[v].empty())cnt[v]=INF;
 ll ans=0;
 for(int v=n;v>=1;v--){if(ch[v].empty())continue;
  ll sc=0;for(int u:ch[v])sc+=a[u];
  ll b=sc-a[v];
  if(b>=0){cnt[v]=b;continue;}
  ll need=-b;
  vector<int>q={v};
  for(size_t h=0;h<q.size()&&need>0;h++){int w=q[h];
   if(w!=v&&cnt[w]>0){ll take=min(cnt[w],need);ans+=take*(dep[w]-dep[v]);cnt[w]-=take;need-=take;}
   for(int c:ch[w])q.push_back(c);}
 }
 printf("%lld\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
struct Nd{ll xp,np,xm,nm,best;};
int n;vector<Nd>T;vector<ll>a;
Nd mk(int i){return {a[i]+i,a[i]+i,a[i]-i,a[i]-i,0};}
Nd mg(const Nd&L,const Nd&R){return {max(L.xp,R.xp),min(L.np,R.np),max(L.xm,R.xm),min(L.nm,R.nm),
 max({L.best,R.best,L.xp-R.np,R.xm-L.nm})};}
void build(int x,int l,int r){if(l==r){T[x]=mk(l);return;}int m=(l+r)/2;build(2*x,l,m);build(2*x+1,m+1,r);T[x]=mg(T[2*x],T[2*x+1]);}
void upd(int x,int l,int r,int p){if(l==r){T[x]=mk(l);return;}int m=(l+r)/2;
 if(p<=m)upd(2*x,l,m,p);else upd(2*x+1,m+1,r,p);T[x]=mg(T[2*x],T[2*x+1]);}
int main(){int t;scanf("%d",&t);while(t--){int q;scanf("%d %d",&n,&q);
 a.assign(n,0);for(auto&x:a)scanf("%lld",&x);
 T.assign(4*n,{0,0,0,0,0});build(1,0,n-1);
 printf("%lld\n",T[1].best);
 while(q--){int p;ll x;scanf("%d %lld",&p,&x);a[p-1]=x;upd(1,0,n-1,p-1);printf("%lld\n",T[1].best);}}}

