int main(){int t;scanf("%d",&t);while(t--){int n,m;scanf("%d %d",&n,&m);
 vector<ll>a(n),b(m);
 for(auto&x:a)scanf("%lld",&x);for(auto&x:b)scanf("%lld",&x);
 sort(a.begin(),a.end());sort(b.begin(),b.end());
 vector<ll>A(n/2+1,0),B(m/2+1,0);
 for(int p=1;p<=n/2;p++)A[p]=A[p-1]+a[n-p]-a[p-1];
 for(int q=1;q<=m/2;q++)B[q]=B[q-1]+b[m-q]-b[q-1];
 vector<ll>res;
 for(int k=1;;k++){int lo=max(0,2*k-m),hi=min(k,n-k);if(lo>hi)break;
  auto g=[&](int p){return A[p]+B[k-p];};
  while(lo<hi){int mid=(lo+hi)/2;if(g(mid+1)>g(mid))lo=mid+1;else hi=mid;}
  res.push_back(g(lo));}
 printf("%zu\n",res.size());
 for(ll v:res)printf("%lld ",v);
 printf("\n");}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll l1,r1,l2,r2;
ll go(ll a,ll b,ll s){
 if(a>=r1||a+s<=l1||b>=r2||b+s<=l2)return 0;
 if(a>=l1&&a+s<=r1&&b>=l2&&b+s<=r2)return 1;
 ll h=s/2;
 return go(a,b,h)+go(a+h,b,h)+go(a,b+h,h)+go(a+h,b+h,h);}
int main(){int t;scanf("%d",&t);while(t--){scanf("%lld %lld %lld %lld",&l1,&r1,&l2,&r2);
 printf("%lld\n",go(0,0,1LL<<20));}}

