int main(){int t;scanf("%d",&t);while(t--){int n,k;scanf("%d %d",&n,&k);
 vector<ll>d(n+1);for(int i=1;i<=n;i++)scanf("%lld",&d[i]);
 for(int i=0;i<=n+1;i++)par[i]=i;
 vector<int>ord;for(int i=1;i<=n;i++)ord.push_back(i);
 sort(ord.begin(),ord.end(),[&](int a,int b){return d[a]>d[b];});
 ll ans=0;
