#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);
 vector<ll>l(n),r(n);ll base=0,Lall=0;
 for(int i=0;i<n;i++){scanf("%lld %lld",&l[i],&r[i]);base+=r[i]-l[i];Lall+=l[i];}
 vector<int>ord(n);for(int i=0;i<n;i++)ord[i]=i;
 sort(ord.begin(),ord.end(),[&](int a,int b){return r[a]+l[a]>r[b]+l[b];});
 int p=n/2;
 vector<ll>pre(n+1,0);
 for(int i=0;i<n;i++)pre[i+1]=pre[i]+r[ord[i]]+l[ord[i]];
 ll best;
 if(n%2==0)best=pre[p];
 else{best=LLONG_MIN;
  for(int q=0;q<n;q++){int u=ord[q];ll val;
   if(q<p)val=pre[p+1]-(r[u]+l[u])+l[u];
   else val=pre[p]+l[u];
   best=max(best,val);}}
 printf("%lld\n",base+best-Lall);}}
